            int answer;
            ks::SceneManager::hide_background(SCENE_TRANSITION_NONE, 0);
            ks::SceneManager::enable_fill(ks::globals::colors::BLACK);
            ks::SceneManager::update_visuals();
            ks::SceneManager::set_background(ks::background_metas::school_dormhisao, 0, 0, SCENE_TRANSITION_NONE, 0, PALETTE_VARIANT_DEFAULT);
            ks::SceneManager::update_visuals();
            ks::SceneManager::set_line_hash(0x11EC3704);
            ks::SceneManager::show_dialog(ks::definitions::no_char, 101);
